import{describe,it,expect}from"vitest";import{SPACE_MILESTONES_DATA,validateSpaceMilestonesData,getMilestoneById,calculateOrbitPathDashOffset,getOrbitColorByClass}from"../../frontend/space-program-milestones/script.js";describe("Space Program Milestones Dataset Integrity (#577)",()=>{it("contains at least 6 verified mission milestones with orbit animations",()=>{expect(Array.isArray(SPACE_MILESTONES_DATA)).toBe(!0),expect(SPACE_MILESTONES_DATA.length).toBeGreaterThanOrEqual(6)}),it("validates dataset structure and field presence",()=>{const e=validateSpaceMilestonesData(SPACE_MILESTONES_DATA);expect(e.isValid).toBe(!0),expect(e.errors).toEqual([])}),it("verifies key historical milestones exist in sequence",()=>{const e=SPACE_MILESTONES_DATA.map(e=>e.id);expect(e).toContain("founding-aryabhata"),expect(e).toContain("slv3-rohini"),expect(e).toContain("insat-1b"),expect(e).toContain("chandrayaan-1"),expect(e).toContain("mangalyaan-mom"),expect(e).toContain("chandrayaan-3"),expect(e).toContain("aditya-l1"),expect(e).toContain("gaganyaan-program")}),it("ensures every milestone has required orbital properties and achievements",()=>{SPACE_MILESTONES_DATA.forEach(e=>{expect(e).toHaveProperty("year"),expect(e).toHaveProperty("title"),expect(e).toHaveProperty("orbitType"),expect(e.orbitSpec).toHaveProperty("type"),expect(e.orbitSpec).toHaveProperty("color"),expect(Array.isArray(e.keyAchievments)).toBe(!0),expect(e.keyAchievments.length).toBeGreaterThan(0)})})}),describe("Milestone Helper & Lookup Functions",()=>{it("retrieves milestone by valid ID",()=>{const e=getMilestoneById("mangalyaan-mom");expect(e.title).toContain("Mangalyaan"),expect(e.year).toBe(2013)}),it("defaults to first milestone if ID is missing or invalid",()=>{const e=getMilestoneById("non-existent-id");expect(e.id).toBe(SPACE_MILESTONES_DATA[0].id)}),it("assigns correct orbit color codes per orbit class",()=>{expect(getOrbitColorByClass("LEO")).toBe("#38bdf8"),expect(getOrbitColorByClass("GEO")).toBe("#facc15"),expect(getOrbitColorByClass("Mars Orbit")).toBe("#f87171"),expect(getOrbitColorByClass("Lagrange L1 Halo")).toBe("#fb923c")})}),describe("Orbit Animation Math Calculation",()=>{it("calculates 100% stroke dashoffset (hidden) at 0% progress",()=>{expect(calculateOrbitPathDashOffset(0,1e3)).toBe(1e3)}),it("calculates 50% stroke dashoffset at 50% progress",()=>{expect(calculateOrbitPathDashOffset(50,1e3)).toBe(500)}),it("calculates 0 stroke dashoffset (fully visible) at 100% progress",()=>{expect(calculateOrbitPathDashOffset(100,1e3)).toBe(0)}),it("clamps progress bounds between 0 and 100",()=>{expect(calculateOrbitPathDashOffset(-10,1e3)).toBe(1e3),expect(calculateOrbitPathDashOffset(150,1e3)).toBe(0)})});